HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GoldScalpTraderAI · Visual Floor</title>
<style>
:root{color-scheme:dark;--bg:#020d17;--panel:#032131;--line:#16b9db;--cyan:#05ecf4;--gold:#ffdc67;--text:#e9efff;--muted:#9eb8cc;--green:#00e4ba;--red:#ff5364;--amber:#ffd755}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 30%,#073149,#010910 78%);color:var(--text);font:13px/1.25 "Segoe UI",Arial,sans-serif}
main{padding:7px;display:grid;gap:6px;min-height:100vh}.panel,.metric,header,.chartPanel{border:1px solid var(--line);border-radius:7px;background:linear-gradient(115deg,#042536,#011421 75%);box-shadow:inset 0 0 0 2px #00101a,inset 0 0 14px #05729330,0 0 5px #00b5e338}
header{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:8px;align-items:center;padding:8px 12px}.brand h1{margin:0;color:var(--gold);font-size:clamp(24px,2vw,38px)}.brand p{margin:3px 0 0;color:var(--cyan);font-weight:650}.center{text-align:center;color:var(--gold)}.arabic{font-size:22px}.headRight{display:grid;grid-template-columns:1fr 1fr;gap:7px}.clock,.mode{border:1px solid #177b96;border-radius:6px;padding:7px;text-align:center}.clock b{font-size:18px;color:var(--cyan)}.mode b{color:var(--green)}
.marketStrip{display:grid;grid-template-columns:1fr 1fr 2fr 1fr 1fr 1fr;gap:6px}.metric{padding:7px 10px;min-width:0}.label{color:var(--cyan);font-size:11px;font-weight:700;text-transform:uppercase}.value{font-size:20px;font-weight:750;overflow-wrap:anywhere}.green{color:var(--green)!important}.red{color:var(--red)!important}.amber{color:var(--amber)!important}.cyan{color:var(--cyan)!important}.gold{color:var(--gold)!important}.muted{color:var(--muted)}
.floor{display:grid;grid-template-columns:22fr 52fr 30fr;gap:6px;min-height:0}.stack{display:grid;gap:6px;align-content:start}.panel{padding:4px 5px;min-width:0}.panel h2{font-size:13px;color:var(--cyan);border-bottom:1px solid #16708b;margin:0 0 4px;padding:3px 6px;background:linear-gradient(90deg,#07314988,transparent)}.kv{display:flex;justify-content:space-between;gap:8px;padding:3px 7px;border-bottom:1px solid #12445a}.kv:last-child{border-bottom:0}.kv span:last-child{text-align:right;font-variant-numeric:tabular-nums}.reason{padding:6px 8px;color:#d9e6f6;overflow-wrap:anywhere}.action{font-size:30px;font-weight:800;padding:5px 8px}
.chartPanel{display:flex;flex-direction:column;padding:5px;min-height:440px}.chartTools{display:flex;justify-content:space-between;gap:8px;padding:2px 3px 5px}.tabs{display:flex;gap:5px;flex-wrap:wrap}.tabs button{background:#06283b;border:1px solid #167d99;color:var(--text);border-radius:4px;padding:5px 12px;cursor:pointer}.tabs button.active{color:var(--cyan);border-color:var(--cyan);box-shadow:inset 0 0 9px #00d9f033}.chartMeta{color:var(--muted);padding:4px 6px}.chartWrap{position:relative;flex:1;min-height:350px;background:repeating-linear-gradient(90deg,transparent,transparent 49px,#05638914 50px),linear-gradient(#021926,#00121d)}canvas{width:100%;height:100%;display:block}.chartEmpty{position:absolute;inset:0;display:grid;place-items:center;color:var(--muted);pointer-events:none}.legend{display:flex;gap:12px;flex-wrap:wrap;padding:4px 6px;font-size:10px;color:var(--muted)}
.planGrid{display:grid;grid-template-columns:1fr 1fr;gap:0 8px}.shadowList{padding:3px 8px;max-height:92px;overflow:auto}.shadowList div{padding:2px 0;border-bottom:1px solid #11394d}.bottom{display:grid;grid-template-columns:1.05fr 1.25fr 1.25fr 1.25fr;gap:6px}.bottom .panel{min-height:112px}.badge{padding:2px 6px;border:1px solid #236a82;border-radius:999px}.offline{position:fixed;z-index:30;top:104px;left:22%;right:22%;padding:10px;border:1px solid var(--amber);background:#302719;color:var(--gold);text-align:center;border-radius:6px;display:none}.offline.show{display:block}footer{font-size:10px;color:var(--muted);display:flex;justify-content:space-between;padding:1px 5px}
@media(max-width:1150px){header{grid-template-columns:1fr}.center{display:none}.marketStrip{grid-template-columns:repeat(3,1fr)}.floor{grid-template-columns:1fr}.bottom{grid-template-columns:1fr 1fr}.chartPanel{min-height:420px}}
@media(max-width:700px){.marketStrip,.bottom{grid-template-columns:1fr 1fr}.headRight{grid-template-columns:1fr}.floor{display:block}.panel,.chartPanel{margin-bottom:6px}.offline{left:5%;right:5%}}
</style></head><body>
<div id="offline" class="offline">Waiting for dashboard snapshot…</div>
<main>
<header><div class="brand"><h1>🟡 GoldScalpTraderAI</h1><p>M5 SCALPING FLOOR · TIMING INTELLIGENCE · GOVERNED LEARNING</p></div><div class="center"><div class="arabic">بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ</div><small>Discipline today · A bigger tomorrow</small></div><div class="headRight"><div class="clock"><span class="label">Pakistan Time</span><br><b id="clock">—</b><div id="date" class="muted">—</div></div><div class="mode"><span class="label">Mode / Role</span><br><b id="mode">DEMO</b><div class="muted">Read-only visual floor</div></div></div></header>
<section class="marketStrip"><div class="metric"><div class="label">Symbol</div><div id="symbol" class="value gold">—</div></div><div class="metric"><div class="label">Market / Session</div><div id="market" class="value">—</div><div id="session" class="muted">—</div></div><div class="metric"><div class="label">Live Price</div><div><span class="red">SELL <b id="bid">—</b></span> &nbsp; <span class="green">BUY <b id="ask">—</b></span></div><div id="quoteAge" class="muted">quote —</div></div><div class="metric"><div class="label">Spread</div><div id="spread" class="value">—</div></div><div class="metric"><div class="label">Action</div><div id="actionTop" class="value amber">WAIT</div></div><div class="metric"><div class="label">Bot</div><div id="bot" class="value">STARTING</div></div></section>
<section class="floor"><div class="stack"><div class="panel"><h2>🌐 MARKET PICTURE</h2><div id="structureRows"></div></div><div class="panel"><h2>📊 M5 INDICATORS</h2><div id="indicatorRows"></div></div><div class="panel"><h2>🌍 SESSION / NEWS</h2><div class="kv"><span>Hard Session</span><span id="hardSession">—</span></div><div class="kv"><span>Schedule</span><span id="schedule">—</span></div><div class="kv"><span>News</span><span id="news">—</span></div><div id="sessionReason" class="reason muted">—</div></div><div class="panel"><h2>🧬 TIMING INTELLIGENCE</h2><div id="timingRows"></div></div></div>
<div class="chartPanel"><div class="chartTools"><div class="tabs" id="tabs"></div><div class="tabs"><button id="indBtn">Indicators ON</button><button id="drawBtn">Drawings OFF</button><button id="settingsBtn">Bars 60</button></div></div><div id="chartMeta" class="chartMeta">—</div><div class="chartWrap"><canvas id="chart"></canvas><div id="chartEmpty" class="chartEmpty">Waiting for completed candles…</div></div><div class="legend"><span class="green">■ bullish</span><span class="red">■ bearish</span><span class="cyan">line = close path</span><span>volume = lower bars</span></div></div>
<div class="stack"><div class="panel"><h2>🎯 CURRENT SIGNAL / DECISION</h2><div id="action" class="action amber">WAIT</div><div class="kv"><span>Setup</span><span id="setup">—</span></div><div class="kv"><span>Active Family</span><span id="family">—</span></div><div id="reason" class="reason">—</div></div><div class="panel"><h2>📐 TRADE PLAN</h2><div id="plan" class="planGrid"></div></div><div class="panel"><h2>🛑 CURRENT BLOCKER / GATE</h2><div id="gate" class="reason">—</div><div id="system" class="reason muted">—</div></div><div class="panel"><h2>👥 SHADOW / OBSERVE ONLY</h2><div id="shadows" class="shadowList"></div></div><div class="panel"><h2>📈 OPEN / MANAGED TRADE</h2><div id="managed" class="reason">NONE</div></div></div></section>
<section class="bottom"><div class="panel"><h2>🛡️ RISK & ACCOUNT</h2><div id="riskRows"></div></div><div class="panel"><h2>⚙️ EXECUTION / ACTIVITY</h2><div id="execution" class="reason">—</div><div id="activity" class="reason muted">—</div></div><div class="panel"><h2>🧠 LEARNING / GOVERNANCE</h2><div id="learning" class="reason">—</div><div class="reason muted"><span class="badge">Safety non-adaptive</span> <span class="badge">Promotion governed</span></div></div><div class="panel"><h2>🩺 SYSTEM / DATA</h2><div class="kv"><span>Snapshot</span><span id="snapshotState">—</span></div><div class="kv"><span>Age</span><span id="snapshotAge">—</span></div><div class="kv"><span>Charts</span><span id="chartCount">—</span></div><div class="reason muted">CLOSED / UNKNOWN / stale / MT5 errors stay visible. Trading fails closed.</div></div></section>
<footer><span>🔒 localhost-only · no BUY/SELL/MODIFY/CLOSE controls · no MT5 writer authority</span><span id="generated">—</span></footer>
</main>
<script>
const TF=["M1","M5","M15","H1","H4"];let selected="M5",latest=null,indicators=true,drawing=false,candleLimit=60,drawings=[];const $=id=>document.getElementById(id);const val=(v,d="—")=>v===null||v===undefined||v===""?d:String(v);const num=(v,d=3)=>v===null||v===undefined?"—":Number(v).toFixed(d);function row(k,v){return `<div class="kv"><span>${k}</span><span>${val(v)}</span></div>`}function color(el,state){el.classList.remove("green","red","amber","cyan");let s=String(state||"").toUpperCase();if(["OPEN","LIVE","READY","PASS","BUY","HEALTHY","CLEAR"].some(x=>s.includes(x)))el.classList.add("green");else if(["SELL","CLOSED","BLOCK","FAIL","ERROR","HIGH","DEGRADED"].some(x=>s.includes(x)))el.classList.add("red");else if(["WAIT","UNKNOWN","PRE_CLOSE","LIMITED","STARTING"].some(x=>s.includes(x)))el.classList.add("amber");else el.classList.add("cyan")}function tabs(){let b=$("tabs");b.innerHTML="";TF.forEach(tf=>{let x=document.createElement("button");x.textContent=tf;x.className=tf===selected?"active":"";x.onclick=()=>{selected=tf;tabs();draw()};b.appendChild(x)})}function clock(){let n=new Date();$("clock").textContent=new Intl.DateTimeFormat("en-PK",{timeZone:"Asia/Karachi",hour:"numeric",minute:"2-digit",second:"2-digit",hour12:true}).format(n);$("date").textContent=new Intl.DateTimeFormat("en-PK",{timeZone:"Asia/Karachi",weekday:"short",day:"2-digit",month:"short",year:"numeric"}).format(n)}
function paint(d,on,age){latest=d;let m=d.market||{},s=d.session||{},q=d.decision||{},t=d.timing||{},p=d.plan||{},r=d.risk||{};$("symbol").textContent=val(m.symbol);$("market").textContent=val(m.state);color($("market"),m.state);$("session").textContent=val(s.soft_session);$("bid").textContent=num(m.bid);$("ask").textContent=num(m.ask);$("spread").textContent=num(m.spread);$("quoteAge").textContent=m.quote_time_utc?`tick ${m.quote_time_utc}`:"tick unavailable";$("actionTop").textContent=val(q.action,"WAIT");$("action").textContent=val(q.action,"WAIT");color($("actionTop"),q.action);color($("action"),q.action);$("bot").textContent=val(q.bot_status);color($("bot"),q.bot_status);$("mode").textContent=val(d.mode,"DEMO");let st=d.structure||{};$("structureRows").innerHTML=["H4","H1","M15","M5"].map(tf=>row(tf,(st[tf]||{}).state||"UNKNOWN")).join("");let i=(d.indicators||{}).M5||{};$("indicatorRows").innerHTML=row("EMA20",num(i.ema20))+row("EMA50",num(i.ema50))+row("RSI",num(i.rsi,1))+row("ATR",num(i.atr))+row("Flow",i.flow)+row("Volatility",i.volatility);$("hardSession").textContent=val(s.hard_state);$("schedule").textContent=s.schedule_verified?"VERIFIED":"NOT VERIFIED";$("news").textContent=val(s.news_health);$("sessionReason").textContent=val(s.reason);$("timingRows").innerHTML=row("Outcome",t.outcome)+row("Profile",t.profile)+row("M5 Age",t.m5_event_age_bars)+row("Trigger Age",t.trigger_age_seconds==null?"—":`${Number(t.trigger_age_seconds).toFixed(1)}s`)+row("Opportunity",t.opportunity_state)+row("Episode",t.episode_id);$("setup").textContent=val(q.setup);$("family").textContent=val(q.active_family);$("reason").textContent=val(q.reason);$("plan").innerHTML=p.exists?[row("Direction",p.direction),row("Entry",num(p.entry)),row("SL",num(p.stop)),row("TP1",num(p.primary)),row("TP2",num(p.expansion)),row("Gross R",p.gross_r==null?"—":Number(p.gross_r).toFixed(2))].join(""):'<div class="reason muted">No governed trade plan yet.</div>';$("gate").textContent=val(q.gate);$("system").textContent=val(q.system);let sh=d.shadows||[];$("shadows").innerHTML=sh.length?sh.map(x=>`<div>${x}</div>`).join(""):'<div class="muted">No qualified shadow setup in current frame.</div>';let mg=d.management;$("managed").innerHTML=mg?`${val(mg.direction)} #${val(mg.ticket)}<br>Entry ${num(mg.entry)} · SL ${num(mg.stop)} · TP1 ${num(mg.primary)}<br>Manager ${val(mg.manager_action)} · Timing ${val(mg.timing_profile)}`:"NONE — no bot-owned managed Gold position";$("riskRows").innerHTML=row("Decision",r.decision)+row("Risk %",r.risk_pct)+row("Volume",r.volume)+row("Balance",num(m.balance,2))+row("Equity",num(m.equity,2))+row("Free Margin",num(m.free_margin,2));$("execution").textContent=val((d.execution||{}).text);$("activity").textContent=val((d.execution||{}).activity);$("learning").textContent=val((d.learning||{}).text);$("snapshotState").textContent=on?"LIVE":"STALE";$("snapshotAge").textContent=age==null?"—":`${Number(age).toFixed(1)}s`;$("chartCount").textContent=Object.values(d.charts||{}).reduce((a,x)=>a+(x||[]).length,0);$("generated").textContent=`snapshot ${val(d.generated_at_utc)}`;draw()}
function draw(){let c=$("chart"),w=c.parentElement,rows=(((latest||{}).charts||{})[selected]||[]).slice(-candleLimit),r=w.getBoundingClientRect(),px=window.devicePixelRatio||1;c.width=Math.max(300,r.width*px);c.height=Math.max(180,r.height*px);let x=c.getContext("2d");x.scale(px,px);x.clearRect(0,0,r.width,r.height);$("chartEmpty").style.display=rows.length?"none":"grid";$("chartMeta").textContent=`${selected} · ${rows.length} completed candles`;if(!rows.length)return;let hi=Math.max(...rows.map(z=>z.high)),lo=Math.min(...rows.map(z=>z.low)),pad=(hi-lo||1)*.08,top=hi+pad,bot=lo-pad,ph=r.height*.78,vt=r.height*.82,vh=r.height*.15,gap=r.width/rows.length,body=Math.max(2,Math.min(10,gap*.55)),y=p=>8+(top-p)/(top-bot)*(ph-16),vm=Math.max(...rows.map(z=>z.tick_volume||0),1);rows.forEach((z,n)=>{let cx=(n+.5)*gap,col=z.close>=z.open?"#00e4ba":"#ff5364";x.strokeStyle=col;x.fillStyle=col;x.beginPath();x.moveTo(cx,y(z.high));x.lineTo(cx,y(z.low));x.stroke();let a=y(z.open),b=y(z.close);x.fillRect(cx-body/2,Math.min(a,b),body,Math.max(1,Math.abs(b-a)));let bar=(z.tick_volume||0)/vm*vh;x.globalAlpha=.4;x.fillRect(cx-body/2,vt+vh-bar,body,bar);x.globalAlpha=1});if(indicators){x.strokeStyle="#05ecf4aa";x.beginPath();rows.forEach((z,n)=>{let cx=(n+.5)*gap,cy=y(z.close);n?x.lineTo(cx,cy):x.moveTo(cx,cy)});x.stroke()}drawings.forEach(p=>{if(p>=bot&&p<=top){x.strokeStyle="#ffdc67";x.setLineDash([5,4]);x.beginPath();x.moveTo(0,y(p));x.lineTo(r.width,y(p));x.stroke();x.setLineDash([])}});c.dataset.top=top;c.dataset.bot=bot;let z=rows[rows.length-1];$("chartMeta").textContent=`${selected} · O ${num(z.open)} H ${num(z.high)} L ${num(z.low)} C ${num(z.close)} · ${rows.length} completed candles`}
async function poll(){try{let r=await fetch("/api/snapshot",{cache:"no-store"}),x=await r.json(),o=$("offline");if(!x.ok||!x.snapshot){o.textContent=x.message||"Snapshot unavailable";o.classList.add("show");return}o.classList.toggle("show",!x.online);o.textContent=x.message||"BOT OFFLINE / SNAPSHOT STALE";paint(x.snapshot,x.online,x.age_seconds)}catch(e){let o=$("offline");o.textContent="Dashboard server / snapshot unavailable";o.classList.add("show")}}
$("indBtn").onclick=()=>{indicators=!indicators;$("indBtn").textContent=`Indicators ${indicators?"ON":"OFF"}`;draw()};$("drawBtn").onclick=()=>{drawing=!drawing;$("drawBtn").textContent=`Drawings ${drawing?"ON":"OFF"}`};$("settingsBtn").onclick=()=>{candleLimit=candleLimit===60?40:candleLimit===40?80:60;$("settingsBtn").textContent=`Bars ${candleLimit}`;draw()};$("chart").addEventListener("click",e=>{if(!drawing||!latest)return;let c=$("chart"),r=c.getBoundingClientRect(),top=Number(c.dataset.top),bot=Number(c.dataset.bot);if(!Number.isFinite(top)||!Number.isFinite(bot))return;let ph=r.height*.78,p=top-((e.clientY-r.top-8)/(ph-16))*(top-bot);drawings.push(p);draw()});tabs();clock();setInterval(clock,1000);setInterval(poll,1000);addEventListener("resize",draw);poll();
</script></body></html>'''
